/** Contract-based test harness for the initialize entry point
  */
pub fn testInitializeCB() -> HarnessResult
{
  // [InvokeEntryPoint]: Invoke the entry point
  crate::manage_regulator_interface_process_manage_regulator_interface_initialize();

  // [RetrieveOutState]: retrieve values of the output ports via get operations and GUMBO declared local state variable
  let api_control_basis = get_control_basis();
  let api_interface_facts = get_interface_facts();
  let api_regulator_feedback = get_regulator_feedback();

  // [CheckPost]: invoke the oracle function
  if !GUMBOX::initialize_IEP_Post (api_control_basis, api_interface_facts, api_regulator_feedback) {
    return HarnessResult::FailedPostcondition(
      TestCaseError::Fail("Postcondition failed: incorrect output behavior".into())
    );
  }

  return HarnessResult::Passed
}

#[macro_export]
macro_rules!
testInitializeCB_macro {
  (
    $test_name: ident,
    config: $config:expr
  ) => {
    proptest!{
      #![proptest_config($config)]
      #[test]
      #[serial]
      fn $test_name(empty in ::proptest::strategy::Just(())) {
        match $crate::test::util::cb_apis::testInitializeCB() {
          $crate::test::util::cb_apis::HarnessResult::RejectedPrecondition => {
            unreachable!("This branch is infeasible")
          }
          $crate::test::util::cb_apis::HarnessResult::FailedPostcondition(e) => {
            return Err(e)
          }
          $crate::test::util::cb_apis::HarnessResult::Passed => { }
        }
      }
    }
  };
}

/** Contract-based test harness for the compute entry point
  *
  * @param api_current_temperature incoming data port
  * @param api_desired_settings incoming data port
  * @param api_regulator_mode incoming data port
  */
pub fn testComputeCB(
  api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  api_desired_settings: Isolette_Thermostat_Rust::DesiredTemperatureSettings,
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode) -> HarnessResult
{
  // Initialize the app
  crate::manage_regulator_interface_process_manage_regulator_interface_initialize();

  // [PutInPorts]: Set values on the input ports
  put_current_temperature(api_current_temperature);
  put_desired_settings(api_desired_settings);
  put_regulator_mode(api_regulator_mode);

  // [InvokeEntryPoint]: Invoke the entry point
  crate::manage_regulator_interface_process_manage_regulator_interface_timeTriggered();

  // [RetrieveOutState]: retrieve values of the output ports via get operations and GUMBO declared local state variable
  let api_control_basis = get_control_basis();
  let api_interface_facts = get_interface_facts();
  let api_regulator_feedback = get_regulator_feedback();

  // [CheckPost]: invoke the oracle function
  if !GUMBOX::compute_CEP_Post(api_current_temperature, api_desired_settings, api_regulator_mode, api_control_basis, api_interface_facts, api_regulator_feedback) {
    return HarnessResult::FailedPostcondition(TestCaseError::Fail("Postcondition failed: incorrect output behavior".into()));
  }

  return HarnessResult::Passed
}

/** Contract-based test harness for the compute entry point
  */
pub fn testComputeCB_container(container: PreStateContainer) -> HarnessResult
{
  return testComputeCB(container.api_current_temperature, container.api_desired_settings, container.api_regulator_mode)
}

